/// The backend's validSupportEvent, field by field: returns every value of a
/// timeline entry that would make it reject the whole report.
List<String> backendSupportViolations(Map<String, Object?> event) {
  final problems = <String>[];
  if (event.length > 40) problems.add('too many fields');
  final source = event['source'];
  for (final entry in event.entries) {
    final key = entry.key;
    final value = entry.value;
    if (key == 'source' || key == 'timestamp') continue;
    if (source == 'application') {
      final values = backendApplicationEnums[key];
      final range = backendApplicationNumbers[key];
      if (values != null) {
        if (value is! String || !values.contains(value)) {
          problems.add('$key=$value');
        }
      } else if (range != null) {
        if (value is! int || value < range.$1 || value > range.$2) {
          problems.add('$key=$value');
        }
      } else {
        problems.add('unknown application field $key');
      }
    } else if (source == 'native') {
      if (key == 'area') continue;
      if (key == 'event') {
        if (!(backendNativeEvents[event['area']]?.contains(value) ?? false)) {
          problems.add('event=${event['area']}/$value');
        }
      } else if (key == 'code' && value is int) {
        if (value < 0 || value > 0xffffffff) problems.add('$key=$value');
      } else if (backendNativeEnums[key] case final values?) {
        if (value is! String || !values.contains(value)) {
          problems.add('$key=$value');
        }
      } else if (backendNativeNumbers.contains(key)) {
        if (value is! int || value < 0 || value > 0xffffffff) {
          problems.add('$key=$value');
        }
      } else {
        problems.add('unknown native field $key');
      }
    } else {
      problems.add('source=$source');
    }
  }
  return problems;
}

/// [backendSupportViolations] for one local trace line, as the support
/// export would send it.
List<String> backendTraceLineViolations(String line) {
  final event = <String, Object?>{'source': 'application'};
  for (final part in line.split(' ').skip(1)) {
    final separator = part.indexOf('=');
    final key = part.substring(0, separator);
    final value = part.substring(separator + 1);
    event[key] = backendApplicationNumbers.containsKey(key)
        ? int.tryParse(value) ?? value
        : value;
  }
  return backendSupportViolations(event);
}
